# 開發時 src\pcx_mcp\server.py 往上兩層是專案資料夾（uv 以 editable 方式安裝，__file__ 指回 src）；
# 裝進 plugin 時這一層是內附 Python 的 Lib\，沒有 pyproject.toml，_out_dir 靠這點分辨兩種情境
PROJECT_ROOT = Path(__file__).resolve().parents[2]


def _money(v: Decimal | None) -> str:
    if v is None:
        return "-"
    return f"{v:,.0f}" if v == v.to_integral_value() else f"{v:,}"


def _num(v: Decimal | None) -> str:
    return "-" if v is None else f"{v.normalize():f}"


# mcp 2.x 只有 ToolError 的訊息會送回模型，其他例外一律變成「Error executing tool」，
# 所以預期內的錯誤都要轉成 ToolError，模型才知道要改哪個參數
def _load(path: str):
    p = Path(path)
    if not p.is_absolute():
        raise ToolError(f"path 要給絕對路徑，收到的是：{path}")
    if not p.is_file():
        raise ToolError(f"找不到檔案：{path}。請確認使用者已從 PCCES 匯出 xml，並放在這個位置。")
    try:
        return parse_etender(p)
    except (ValueError, ET.ParseError) as exc:
        raise ToolError(f"{path} 讀不成預算書：{exc}") from exc


def _line(it: PayItem, detailed: bool, total: PayItem | None = None) -> str:
    # 小計列沒有項次；只有頂層最後那列是總計，中間的小計列（PCX-003）不能也標成總計
    blank = "（總計）" if it is total else "（小計）" if it.kind == SUBTOTAL_KIND else "（無項次）"
    head = f"{it.item_no or blank} {it.description}"
    if not detailed:
        return f"{head}　複價 {_money(it.amount)}"
    parts = [head, f"單位 {it.unit or '-'}", f"數量 {_num(it.quantity)}",
             f"單價 {_money(it.price)}", f"複價 {_money(it.amount)}"]
    if it.ref_item_code:
        parts.append(f"工項代碼 {it.ref_item_code}")
    if it.percent:
        parts.append(f"比例 {_num(it.percent)}%")
    return "　".join(parts)


def _grand_total(b: Budget) -> PayItem | None:
    return b.items[-1] if b.items and b.items[-1].kind == SUBTOTAL_KIND else None


def _render(b: Budget, max_level: int, response_format: str,
            source: str | None = None, warnings: list[str] | None = None) -> str:
    """XML 與資料庫兩支讀取工具共用的排版；資料庫版只多一行來源，項目樹與檢查逐字相同。"""
    detailed = response_format == "detailed"
    out = [
        f"工程：{b.title}（{b.contract_no}）",
        f"主辦機關：{b.procuring_entity}　地點：{b.location}",
        f"總價：{_money(b.total_amount)} 元",
    ]
    if source:
        out.append(source)
    out += ["", "項目："]
    for level, it in b.iter_items():
        if max_level >= 0 and level > max_level:
            continue
        out.append("　" * (level + 1) + _line(it, detailed, _grand_total(b)))
    problems = (warnings or []) + check_consistency(b)
    out.append("")
    out.append("金額檢查：全部對得起來" if not problems else "金額檢查：有 %d 處對不起來" % len(problems))
    out.extend(f"　{p}" for p in problems)
    return "\n".join(out)


# ---------- 帶 item：單項明細與單價分析組成 ----------

_ITEM_KIND = {
    "analysis": "有單價分析的工項（analysis）",
    "general": "一般項（general）",
    "variablePrice": "變動單價項（variablePrice）",
    "formula": "公式項（formula）",
    "mainItem": "母項（mainItem）",
}


def _comp_kind(r: ComponentRow) -> str:
    if r.kind == "general":
        n = len(r.shared)
        return f"一般工料（單價全案共用，另有 {n} 個分析用到）" if n else "一般工料（單價全案共用，沒有別的分析用到）"
    if r.kind == "variablePrice":
        return "變動單價工料（單價只屬這個分析）"
    if r.kind == "variableSumPercentage":
        return f"% 類 {_num(r.percent)}%（跟著其他列重算）"
    if r.kind == "analysis":
        return "巢狀分析（子分析）"
    return f"itemKind={r.kind or '（空）'}"


def _editable(r: ComponentRow) -> str:
    q, p = r.quantity_block, r.price_block
    if q is None and p is None:
        return "可改數量、單價"
    if q == p:
        return f"不能改：{q}"
    if q is None:
        return f"可改數量；單價不能改：{p}"
    if p is None:
        return f"可改單價；數量不能改：{q}"
    return f"數量不能改：{q}；單價不能改：{p}"


def _render_item(v: ItemView, doc: ETenderDocument, response_format: str, source: str | None = None) -> str:
    """XML 與資料庫兩支讀取工具帶 item 時共用的排版；資料庫版只多一行來源。"""
    detailed = response_format == "detailed"
    out = [f"工程：{doc.title()}（{doc.contract_no}）"]
    if source:
        out.append(source)
    head = [_ITEM_KIND.get(v.kind, f"itemKind={v.kind or '（空）'}")]
    if v.ref_item_code:
        head.append(f"工項代碼 {v.ref_item_code}")
    head += [f"單位 {v.unit or '-'}", f"數量 {_num(v.quantity)}", f"單價 {_money(v.price)}", f"複價 {_money(v.amount)}"]
    out += ["", f"項次 {v.path} {v.name}", "　".join(head)]

    if v.children is not None:
        out.append(f"這是母項：複價＝子項加總（不含小計列），沒有單價分析，pcces_write_budget 不能直接改。底下 {len(v.children)} 項：")
        out.extend(f"・{c.path} {c.name}（{c.hint}）" + (f"　複價 {_money(c.amount)}" if detailed else "") for c in v.children)
        out.append("要看其中一項的明細與單價分析組成，把 item 換成那一項的項次再叫一次。")
        return "\n".join(out)
    if v.kind == "formula":
        out.append("公式項：金額由 PCCES 依公式算，pcces_write_budget 不能改，改了也會在重新總計時被蓋掉；請在 PCCES 裡改公式。")
        return "\n".join(out)
    if not v.has_analysis:
        if v.kind in ("general", "variablePrice"):
            out.append(f"沒有單價分析：數量、單價直接用 pcces_write_budget 改，edits 寫 "
                       f'{{"item": "{v.path}", "quantity": {_num(v.quantity)}, "price": {_num(v.price)}}}（只改一個就只給一個），'
                       f"不帶 component。數量最多 {v.quantity_decimals} 位小數、單價最多 {PRICE_MAX_DECIMALS} 位小數。")
        else:
            out.append(f"itemKind={v.kind or '（空）'}：pcces_write_budget 只改 analysis、general、variablePrice 的葉項。")
        return "\n".join(out)
    a = v.analysis
    if a is None:
        out.append(f"標成有單價分析，但單價分析表（CostBreakdownList）沒有工項代碼 {v.ref_item_code}，看不到組成。")
        return "\n".join(out)

    shared = f"（詳細表 {'、'.join(a.items)} 共用這個分析，改組成這幾列一起變）" if len(a.items) > 1 else ""
    out += ["", f"單價分析 {a.code}：分析單價 {_money(a.price)}，analysisOutputQuantity {a.output_quantity}，"
                f"組成 {len(a.rows)} 列{shared}"]
    if detailed:
        out.append(f"詳細表用到這個分析的項次：{'、'.join(a.items) or '（沒有）'}")
        out.append(f"單價分析表的位數：數量 {a.digits.quantity} 位、單價 {a.digits.price} 位、複價 {a.digits.amount} 位小數。"
                   "重算規則：組成複價＝round(round(數量)×round(單價))；分析單價＝round(其他列合計×（1＋% 類費率）÷ analysisOutputQuantity)；"
                   "% 類那一列＝分析單價 × analysisOutputQuantity − 其他列合計")
    if a.block:
        out.append(f"這個分析不能用 component 改：{a.block}；請在 PCCES 裡改。")
    for r in a.rows:
        parts = [f"{r.no}. {r.code} {r.name}", f"單位 {r.unit or '-'}", f"數量 {_num(r.quantity)}",
                 f"單價 {_money(r.price)}", f"複價 {_money(r.amount)}", _comp_kind(r)]
        if not a.block:
            parts.append(_editable(r))
        out.append("　".join(parts))
        if detailed and r.shared:
            out.append("　　用到它的其他分析：" + "；".join(
                f"{s.code} {s.name}（詳細表 {'、'.join(s.items) or '沒有'}）" for s in r.shared))
    if not a.block:
        ok = next((r for r in a.rows if r.quantity_block is None), None)
        out.append("")
        out.append("這一項的數量可以直接改（不帶 component）；單價由單價分析算出來，要改就改組成：")
        if ok is not None:
            # 底稿的組成數量可能比單價分析表的位數多（Class01 的 0.025），範例照位數進位，照抄才不會被寫入工具擋下
            q = None if ok.quantity is None else rnd(ok.quantity, a.digits.quantity)
            general = any(r.kind == "general" and r.price_block is None for r in a.rows)
            out.append(f'pcces_write_budget 的 edits 寫 {{"item": "{v.path}", "component": "{ok.code}", "quantity": {_num(q)}}}'
                       f"（改單價就給 price），數量最多 {a.digits.quantity} 位小數、單價最多 {PRICE_MAX_DECIMALS} 位小數。"
                       + ("一般工料改單價會連帶重算其他用到它的分析（上面標了另有幾個），資源統計的單價也一起改；" if general else "")
                       + "工具會重算分析單價，再更新詳細表用到這個分析的每一列。")
        else:
            out.append("這個分析沒有可以用 component 改的列；請在 PCCES 裡改。")
    return "\n".join(out)


def _load_doc(path: str) -> ETenderDocument:
    p = Path(path)
    if not p.is_absolute():
        raise ToolError(f"path 要給絕對路徑，收到的是：{path}")
    if not p.is_file():
        raise ToolError(f"找不到檔案：{path}。請確認使用者已從 PCCES 匯出 xml，並放在這個位置。")
    try:
        return parse_document(p)
    except ValueError as exc:
        raise ToolError(f"{path} 讀不成預算書：{exc}") from exc


def _item(doc: ETenderDocument, item: str, response_format: str, source: str | None = None) -> str:
    try:
        v = item_view(doc, item)
    except EditError as exc:
        raise ToolError(f"{exc}。要看整棵項目樹就不帶 item、max_level=-1。") from exc
    return _render_item(v, doc, response_format, source)


@mcp.tool()
def pcces_read_budget(
    path: str,
    max_level: int = 1,
    response_format: Literal["concise", "detailed"] = "concise",
    item: str | None = None,
) -> str:
    """讀一份 PCCES 預算書（電子標單 XML），回傳工程基本資料、章節項目樹、總價與金額檢查結果；帶 item 改成回那一項的明細與單價分析組成。

    path：PCCES 匯出的 .xml 絕對路徑。
    max_level：項目樹列到第幾層，0＝只列壹、貳這一層，1＝再列一、二…（預設），-1＝全部。帶 item 時不用。
    response_format：concise 只列項次、名稱、複價；detailed 另列單位、數量、單價、工項代碼。
    金額檢查會核對「子項加總（不含小計列）＝上層複價」「數量×單價＝複價」「小計列＝它該加的各列」「頂層加總＝總價」，
    對不起來的逐條列出。
    item：選填，項次，寫法跟 pcces_write_budget 的 item 相同（例 壹.二.2）。給了就不列項目樹，改回這一項的
      項次、名稱、單位、數量、單價、複價、itemKind；有單價分析再列分析單價、analysisOutputQuantity 與每一列組成
      （序號、工料代碼、名稱、單位、數量、單價、複價、種類：一般工料／變動單價工料／% 類／巢狀分析），
      並標出每一列能不能用 pcces_write_budget 的 component 改數量、單價，不能改的寫原因。指到母項時列出底下的項次。
      這時 response_format 的 detailed 另列詳細表用到這個分析的項次、位數與重算規則、一般工料還被哪些分析用到。
    """
    if item is not None:
        return _item(_load_doc(path), item, response_format)
    return _render(_load(path), max_level, response_format)


@mcp.tool()
def pcces_find_items(
    path: str,
    keyword: str | None = None,
    item_code: str | None = None,
    limit: int = 20,
) -> str:
    """在 PCCES 預算書（電子標單 XML）裡找工項，回傳所在章節、單位、數量、單價、複價、工項代碼。

    path：PCCES 匯出的 .xml 絕對路徑。
    keyword：名稱關鍵字，子字串比對、不分大小寫，例如「混凝土」「舖地磚」。
    item_code：工項代碼（公共工程編碼）前綴，例如「0331」找全部預拌混凝土。
    keyword 與 item_code 至少給一個，兩個都給時要同時符合。limit 是最多回傳幾筆。
    """
    if not keyword and not item_code:
        raise ToolError("keyword 與 item_code 至少要給一個，例如 keyword=\"混凝土\" 或 item_code=\"0331\"")
    b = _load(path)
    hits = find_items(b, keyword=keyword, item_code=item_code)
    if not hits:
        return f"在「{b.title}」找不到符合的工項（keyword={keyword!r}，item_code={item_code!r}）。"
    out = [f"在「{b.title}」找到 {len(hits)} 筆" + (f"，列前 {limit} 筆" if len(hits) > limit else "") + "："]
    for chain, it in hits[:limit]:
        where = " > ".join(f"{p.item_no} {p.description}" for p in chain) or "（頂層）"
        out.append(f"・{where} > {_line(it, detailed=True, total=_grand_total(b))}")
    return "\n".join(out)


# ---------- 資源統計（工料總量） ----------

# detailed 每筆最多列幾處用途；數量核對不符時最多舉幾筆例子
USE_LIMIT = 10
GAP_EXAMPLES = 5

_RES_KIND = {
    "general": "一般工料",
    "variablePrice": "變動單價（單價屬各分析，資源統計不列）",
    "variableSumPercentage": "% 類（資源統計不列單價）",
    "formula": "公式（#，資源統計不列單價）",
    "analysis": "分析項（沒有組成）",
}


def _check_resource_args(keyword: str | None, item_code: str | None, limit: int) -> None:
    if not (keyword and keyword.strip()) and not (item_code and item_code.strip()):
        raise ToolError("keyword 與 item_code 至少要給一個，例如 keyword=\"鋼筋\"（工料名稱關鍵字）或 item_code=\"M0321\"（工料代碼前綴）")
    if limit < 1:
        raise ToolError(f"limit 要是 1 以上的整數（最多列幾筆），收到的是 {limit}")


def _criteria(keyword: str | None, item_code: str | None) -> str:
    parts = []
    if keyword and keyword.strip():
        parts.append(f"名稱含「{keyword.strip()}」")
    if item_code and item_code.strip():
        parts.append(f"工料代碼開頭是「{item_code.strip()}」")
    return "且".join(parts)


def _via(u: Use) -> str:
    if not u.via:
        return "直接列在詳細表"
    # 頂層分析的名稱就是詳細表那一列的名稱（對照文件 2.2），只寫代碼；巢狀的才寫名稱
    return f"經單價分析 {u.via[0][0]}" + "".join(f" ＞ 巢狀 {c} {n}" for c, n in u.via[1:])


def _resource_line(r: Resource) -> str:
    return "　".join([f"・{r.code} {r.name}", f"單位 {r.unit or '-'}", _RES_KIND.get(r.kind, f"itemKind={r.kind or '（空）'}"),
                     f"數量 {_num(r.quantity)}", f"單價 {_money(r.price)}", f"複價 {_money(r.amount)}"])


def _total_line(hits: list[Resource]) -> str:
    amount = sum((r.amount or Decimal(0) for r in hits), Decimal(0))
    units = list(dict.fromkeys(r.unit for r in hits))
    if len(units) == 1:
        qty = sum((r.quantity or Decimal(0) for r in hits), Decimal(0))
        return f"合計（{len(hits)} 筆，單位都是 {units[0] or '（空）'}）：數量 {_num(qty)}　複價 {_money(amount)}"
    return f"合計（{len(hits)} 筆）：複價 {_money(amount)}；單位不一致（{'、'.join(u or '（空）' for u in units)}），不加總數量"


def _gap_lines(rep: ResourceReport, shown: list[Resource]) -> list[str]:
    if rep.estimated:
        return []
    if not rep.gaps:
        return ["數量核對：資源統計的數量都等於詳細表＋單價分析展開加總。"]
    codes = {r.code for r in shown}
    mine = [g for g in rep.gaps if g.code in codes]
    if mine:
        out = [f"數量核對：資源統計的數量跟詳細表＋單價分析展開加總對不上，全案 {len(rep.gaps)} 筆，上面列出的有 {len(mine)} 筆："]
    else:
        out = [f"數量核對：上面列出的都對得上，但全案有 {len(rep.gaps)} 筆資源統計的數量跟詳細表＋單價分析展開加總對不上，例如："]
    for g in mine or rep.gaps[:GAP_EXAMPLES]:
        listed = "沒有這一筆" if g.listed is None else _num(g.listed)
        out.append(f"・{g.code} {g.name}：資源統計 {listed}、展開 {_num(g.expanded)}")
    out.append("資源統計是匯出當時算的；常見原因是這份檔被 pcces_write_budget 改過、還沒在 PCCES 重新總計（寫入工具照抄資源統計的數量與複價）。"
               "請使用者把這份匯入 PCCES、重新總計後再匯出，拿新檔再查；在那之前上面的數量、複價是資源統計原值，不含之後的改動。")
    return out


def _render_resources(doc: ETenderDocument, rep: ResourceReport, keyword: str | None, item_code: str | None,
                      limit: int, response_format: str, source: str | None = None) -> str:
    """XML 與資料庫兩支資源統計工具共用的排版；資料庫版只多一行來源。"""
    out = [f"工程：{doc.title()}（{doc.contract_no}）"]
    if source:
        out.append(source)
    if rep.estimated:
        out.append("這份檔沒有資源統計（ResourceList）：下面的數量、複價是從詳細表＋單價分析展開推算的"
                   "（數量＝Σ round(用量, 4)，複價＝Σ round(用量 × 組成單價, 4)，跟 PCCES 4.3 重新總計同一套算法），"
                   "不是 PCCES 匯出的值；名稱、單位取第一處用到它的地方。")
    if rep.skipped:
        out.append(f"另有 {len(rep.skipped)} 列詳細表標成有單價分析、單價分析表卻找不到，沒有展開（用到的工料數量會少算）："
                   + "、".join(rep.skipped[:GAP_EXAMPLES]) + ("…" if len(rep.skipped) > GAP_EXAMPLES else ""))
    crit = _criteria(keyword, item_code)
    if not rep.hits:
        out.append(f"資源統計（全案 {rep.n_resources} 筆工料）裡找不到{crit}的工料。"
                   "資源統計只收工料；雜費、營業稅這類詳細表直接列的費用項請看項目樹或用 pcces_find_items。")
        return "\n".join(out)
    shown = rep.hits[:limit]
    more = f"，列前 {limit} 筆（依工料代碼排）" if len(rep.hits) > limit else "（依工料代碼排）"
    out.append(f"資源統計（全案 {rep.n_resources} 筆工料）裡{crit}的有 {len(rep.hits)} 筆{more}：")
    detailed = response_format == "detailed"
    for r in shown:
        out.append(_resource_line(r))
        if not detailed:
            continue
        if not r.uses:
            out.append("　詳細表＋單價分析展開找不到用到它的地方")
            continue
        uses = sorted(r.uses, key=lambda u: u.quantity, reverse=True)  # reverse 仍是穩定排序：同用量照詳細表順序
        out.append(f"　用在 {len(uses)} 處（照用量由大到小）：")
        out.extend(f"　　{u.path} {u.name}：{_via(u)}，用量 {_num(u.quantity)}" for u in uses[:USE_LIMIT])
        if len(uses) > USE_LIMIT:
            out.append(f"　　另有 {len(uses) - USE_LIMIT} 處")
    if len(rep.hits) > 1:
        out.append(_total_line(rep.hits))
    out.extend(_gap_lines(rep, shown))
    return "\n".join(out)


def _resources(doc: ETenderDocument, keyword: str | None, item_code: str | None, limit: int,
               response_format: str, source: str | None = None) -> str:
    rep = find_resources(doc, keyword=keyword, item_code=item_code)
    return _render_resources(doc, rep, keyword, item_code, limit, response_format, source)


@mcp.tool()
def pcces_find_resources(
    path: str,
    keyword: str | None = None,
    item_code: str | None = None,
    limit: int = 20,
    response_format: Literal["concise", "detailed"] = "concise",
) -> str:
    """查 PCCES 預算書（電子標單 XML）的資源統計（工料總量）：全案某種工料總共用多少，例如鋼筋幾噸、混凝土用量、模板、人工、機具，回工料代碼、單位、數量、單價、複價；detailed 再列每筆用在詳細表哪些項目。

    path：PCCES 匯出的 .xml 絕對路徑。
    keyword：工料名稱關鍵字，子字串比對、不分大小寫，例如「鋼筋」「混凝土」「模板」。
    item_code：工料代碼前綴，例如「M0321」。
    keyword 與 item_code 至少給一個，兩個都給時要同時符合。limit：最多列幾筆，合計照全部符合的算。結果依工料代碼排。
    response_format：concise 每筆列工料代碼、名稱、單位、種類（一般工料／變動單價／% 類／公式）、數量、單價、複價；
      符合的有兩筆以上時加一行合計，單位都相同才加總數量，不同就只合計複價並講明。
      detailed 每筆再列用在詳細表哪幾項：項次（寫法同 pcces_write_budget 的 item）、名稱、經過哪個單價分析（巢狀的一層層列）、
      那一處的用量；每筆最多 10 處、照用量由大到小，其餘寫另有幾處。
    數量、單價、複價照檔案裡資源統計（ResourceList）的原值，是 PCCES 匯出時算的；另拿詳細表＋單價分析展開加總核對數量，
    對不上的逐筆列出（常見原因是 pcces_write_budget 改過、還沒在 PCCES 重新總計）。檔案沒有資源統計時改用展開推算並講明。
    只收工料；雜費、營業稅這類詳細表直接列的費用項用 pcces_find_items 找。
    """
    _check_resource_args(keyword, item_code, limit)
    return _resources(_load_doc(path), keyword, item_code, limit, response_format)


def _db(fn, *args):
    # 環境壞了（要使用者處理）與代碼給錯（模型自己改）分開講，兩種都給得出下一步
    try:
        return fn(*args)
    except ProjectNotFound as exc:
        raise ToolError(f"{exc}請先叫 pcces_list_db_budgets 看各工程名稱，再用正確的工程代碼重叫。") from exc
    except DbUnavailable as exc:
        raise ToolError(f"{exc}也可以請使用者從 PCCES 匯出預算書 XML，改用 pcces_read_budget 讀。") from exc


@mcp.tool()
def pcces_list_db_budgets() -> str:
    """列出這台電腦 PCCES 資料庫裡有哪些預算書：工程代碼、名稱、總價、詳細表列數，不必先匯出 XML。

    只能在裝了 PCCES 的電腦上用（本機 SQL Server Express 的 Pcces 資料庫，唯讀查詢）。
    要讀其中一份，把工程代碼交給 pcces_read_db_budget 的 project_code。
    """
    rows = _db(list_budgets)
    if not rows:
        return "PCCES 資料庫裡一份預算書都沒有。請使用者先在 PCCES「預算書編製」建立或匯入工程。"
    out = [f"PCCES 資料庫裡有 {len(rows)} 份預算書（工程代碼　名稱　總價　詳細表列數）："]
    for s in rows:
        out.append(f"・{s.code}　{s.name}　總價 {_money(s.total)} 元　詳細表 {s.n_items} 列")
    out.append("要讀其中一份，把工程代碼交給 pcces_read_db_budget。")
    return "\n".join(out)


@mcp.tool()
def pcces_read_db_budget(
    project_code: str,
    max_level: int = 1,
    response_format: Literal["concise", "detailed"] = "concise",
    item: str | None = None,
) -> str:
    """直接從這台電腦的 PCCES 資料庫讀一份預算書，回傳工程基本資料、章節項目樹、總價與金額檢查結果，不必先匯出 XML；帶 item 改成回那一項的明細與單價分析組成。

    project_code：工程代碼，例如 ArchEx001；不知道代碼就先叫 pcces_list_db_budgets。
    max_level：項目樹列到第幾層，0＝只列壹、貳這一層，1＝再列一、二…（預設），-1＝全部。帶 item 時不用。
    response_format：concise 只列項次、名稱、複價；detailed 另列單位、數量、單價、工項代碼。
    item：選填，項次（例 壹.二.2），跟 pcces_read_budget 的 item 相同：回這一項與單價分析組成、每一列能不能用
      pcces_write_budget 的 component 改。pcces_write_budget 要用 XML 當底稿，改值前先請使用者從 PCCES 匯出。
    輸出格式與 pcces_read_budget 相同，只多一行資料來源；金額檢查的規則也相同。
    只能在裝了 PCCES 的電腦上用，查詢唯讀。
    """
    if not project_code or not project_code.strip():
        raise ToolError("project_code 不能是空的；先叫 pcces_list_db_budgets 看有哪些工程代碼。")
    source = f"來源：PCCES 資料庫 {server_name()}／Pcces（唯讀查詢）"
    if item is not None:
        doc = _db(read_document, project_code)
        return _item(doc, item, response_format,
                     source + "；pcces_write_budget 要用 XML 當底稿，改值前先請使用者從 PCCES 匯出")
    b, warnings = _db(read_budget, project_code)
    return _render(b, max_level, response_format, source=source, warnings=warnings)


@mcp.tool()
def pcces_find_db_resources(
    project_code: str,
    keyword: str | None = None,
    item_code: str | None = None,
    limit: int = 20,
    response_format: Literal["concise", "detailed"] = "concise",
) -> str:
    """直接從這台電腦的 PCCES 資料庫查資源統計（工料總量）：全案某種工料總共用多少，例如鋼筋幾噸、混凝土用量、模板、人工、機具，回工料代碼、單位、數量、單價、複價；detailed 再列每筆用在詳細表哪些項目，不必先匯出 XML。

    project_code：工程代碼，例如 ArchEx001；不知道代碼就先叫 pcces_list_db_budgets。
    keyword、item_code、limit、response_format 跟 pcces_find_resources 相同：keyword 是工料名稱關鍵字（不分大小寫）、
      item_code 是工料代碼前綴，至少給一個；detailed 每筆再列用在哪幾項、經過哪個單價分析、那一處的用量（最多 10 處）。
    輸出格式與 pcces_find_resources 相同，只多一行資料來源。
    數量與複價照 PCCES 4.3 重新總計的算法，從詳細表＋單價分析展開重算（不取資料庫裡上次重新總計留下的快取，
    沒重新總計過的工程快取會缺值）；所以跟一份沒重新總計就匯出的舊 XML 比，複價可能不同。
    只能在裝了 PCCES 的電腦上用，查詢唯讀。
    """
    _check_resource_args(keyword, item_code, limit)
    if not project_code or not project_code.strip():
        raise ToolError("project_code 不能是空的；先叫 pcces_list_db_budgets 看有哪些工程代碼。")
    doc = _db(read_document, project_code)
    source = (f"來源：PCCES 資料庫 {server_name()}／Pcces（唯讀查詢）；數量、複價照 PCCES 4.3 重新總計的算法從詳細表＋單價分析展開重算")
    return _resources(doc, keyword, item_code, limit, response_format, source)


# ---------- 重新總計（唯一寫 PCCES 資料庫的工具，寫入由 PCCES 自己的 DLL 做） ----------


def _render_recalc(r: RecalcResult) -> str:
    if r.before is not None and r.after is not None:
        diff = r.after - r.before
        total = f"總價：{_money(r.before)} → {_money(r.after)} 元（{'+' if diff >= 0 else '-'}{_money(abs(diff))}）"
    else:
        total = f"總價：{_money(r.before)} → {_money(r.after)} 元"
    calc = f"，其中 PCCES 的 CalculateAll {r.ms_calculate / 1000:.1f} 秒" if r.ms_calculate is not None else ""
    out = [
        f"已重新總計：{r.name}（{r.code}），PCCES 資料庫 {r.database or server_name()}",
        total,
        f"耗時 {r.wall:.1f} 秒（含啟動{calc}）",
        "",
        "做的事跟 PCCES 畫面上按「重新總計」相同：說明項單價歸零"
        f"（詳細表 {r.memo_rows[0]} 列、工料 {r.memo_rows[1]} 列）、發包權限同步、ItemCalculate.CalculateAll"
        "（詳細表、單價分析、公式項、資源統計）、清掉「要重新總計」旗標與自主檢查結果。",
        f"PCCES {r.pcces_version}：組件內容與內部方法都跟驗證過的相同。",
    ]
    if r.warnings:
        out += ["", "注意："]
        out.extend(f"・{w}" for w in r.warnings)
    out += [
        "",
        "接下來：",
        "1. 自主檢查結果被清掉了（畫面上按重新總計也一樣），交出去之前請使用者在 PCCES 做自主檢查，再製作電子檔。",
        "2. 要看重算後的項目與金額用 pcces_read_db_budget，工料總量用 pcces_find_db_resources。",
    ]
    return "\n".join(out)


@mcp.tool(
    annotations=ToolAnnotations(read_only_hint=False, destructive_hint=True, idempotent_hint=True, open_world_hint=False),
    structured_output=False,
)
def pcces_recalc_db_budget(project_code: str) -> str:
    """在這台電腦的 PCCES 資料庫裡對一本預算書做「重新總計」，等於使用者在 PCCES 畫面按工具列的「重新總計」：重算詳細表、單價分析、公式項（雜費、營業稅這類）與資源統計，回傳重算前後的總價、差額與耗時。

    project_code：工程代碼，例如 ArchEx001；不知道就先叫 pcces_list_db_budgets。
    什麼時候用：pcces_write_budget 產的 XML 匯入 PCCES 之後（匯入的工程沒重算過，公式項與資源統計還是舊的），
      或使用者在 PCCES 改了值還沒重新總計。會改寫資料庫裡這一本的計算結果、清掉自主檢查結果（跟畫面上按一樣），
      不能復原，叫之前先跟使用者確認是哪一本；已經重新總計過的再叫一次不會改到任何值。
    做法：起一支 32 位元的小程式直接叫 PCCES 自己的 DLL（ItemCalculate.CalculateAll），不操作 PCCES 視窗；
      詳細表 3700 列的預算書約 14 秒。
    拒跑（一個字都不寫）的情況，錯誤訊息會講使用者要做什麼：這台 PCCES 的版本或內部 DLL 跟驗證過的不同；
      這本用 PCCES 的舊算法；PCCES 記錄這本正被鎖定編輯；這台的 PCCES 正在執行（分不出它開著哪一本，請使用者先關掉 PCCES）。
    只能在裝了 PCCES 的電腦上用。
    """
    try:
        r = recalc(project_code)
    except RecalcNotFound as exc:
        try:
            available = [s.code for s in list_budgets()]
        except DbUnavailable:
            raise ToolError(f"PCCES 資料庫裡沒有工程代碼「{exc.code}」，沒有寫入任何東西。請先叫 pcces_list_db_budgets 看各工程代碼。") from exc
        raise ToolError(f"{ProjectNotFound(exc.code, available)}沒有寫入任何東西。"
                        "請先叫 pcces_list_db_budgets 看各工程名稱，再用正確的工程代碼重叫。") from exc
    except RecalcError as exc:
        raise ToolError(str(exc)) from exc
    return _render_recalc(r)


class EditSpec(BaseModel):
    item: Annotated[str, Field(description="項次：寫 pcces_read_budget 顯示的項次，例如 壹.一.2；每層只寫一段的預算書把各層用「.」串起來；只能指到葉項")]
    quantity: Annotated[float | None, Field(description="新數量；有 component 時是那一列組成的數量。不改就省略")] = None
    price: Annotated[float | None, Field(description="新單價；有 component 時是那一列組成的單價。沒有 component 時只准沒有單價分析的葉項。不改就省略")] = None
    component: Annotated[str | None, Field(description="選填：改 item 這一項單價分析裡的某一列組成，寫那一列的工料代碼（例 L000006B00002）；代碼與哪些列能改，先用 pcces_read_budget 帶 item 查")] = None


def _out_dir(source: Path) -> Path:
    # 測試靠環境變數把輸出改到暫存資料夾，它不是工具參數；開發專案照舊寫 out\，
    # plugin 沒有專案資料夾，寫在底稿旁邊使用者最好找。檔名由 write_edited 獨占建立，三種情境都不覆蓋既有檔
    env = os.environ.get("PCX_OUT_DIR")
    if env:
        return Path(env)
    if (PROJECT_ROOT / "pyproject.toml").is_file():
        return PROJECT_ROOT / "out"
    return source.parent


def _change_lines(r: WriteResult) -> list[str]:
    price_decimals = r.edit.price_decimals
    out = []
    for c in r.edit.edited:
        parts = []
        if c.quantity_new is not None:
            parts.append(f"數量 {_num(c.quantity_old)} → {_num(c.quantity_new)}")
        if c.price_new is not None:
            parts.append(f"單價 {_money(c.price_old)} → {_money(c.price_new)}" + ("（單價分析重算）" if c.via_analysis else ""))
        line = f"・{c.path} {c.name}：{'；'.join(parts)}；複價 {_money(c.amount_old)} → {_money(c.amount_new)}"
        price = c.price_new if c.price_new is not None else c.price_old
        if price is not None and c.price_used != price:
            line += f"（單價先進位到詳細表的 {price_decimals} 位小數成 {_money(c.price_used)} 再乘數量）"
        out.append(line)
    return out


_COMP_KIND = {"general": "一般工料", "variablePrice": "變動單價", "variableSumPercentage": "% 類，跟著重算"}


def _analysis_lines(r: WriteResult) -> list[str]:
    e = r.edit
    if not e.analyses:
        return []
    out = ["", f"單價分析（{len(e.analyses)} 個）："]
    for a in e.analyses:
        why = f"（一般工料 {'、'.join(a.linked_by)} 單價全案共用，連帶重算）" if a.linked else ""
        out.append(f"・{a.code} {a.name}（詳細表 {'、'.join(a.items)}）：分析單價 {_money(a.price_old)} → {_money(a.price_new)}{why}")
        for c in a.rows:
            parts = []
            if c.quantity_new is not None:
                parts.append(f"數量 {_num(c.quantity_old)} → {_num(c.quantity_new)}")
            if c.price_new is not None and c.kind != "variableSumPercentage":
                parts.append(f"單價 {_money(c.price_old)} → {_money(c.price_new)}")
            parts.append(f"複價 {_money(c.amount_old)} → {_money(c.amount_new)}")
            out.append(f"　{c.code} {c.name}（{_COMP_KIND.get(c.kind, c.kind)}）：{'；'.join(parts)}")
    for res in e.resources:
        out.append(f"・資源統計 {res.code} {res.name} 的單價：{_money(res.price_old)} → {_money(res.price_new)}")
    return out


def _render_write(r: WriteResult) -> str:
    e = r.edit
    diff = e.total_new - (e.total_old or Decimal(0))
    sign = "+" if diff >= 0 else "-"
    out = [
        f"已寫出：{r.path}",
        f"工程：{r.title}（{r.contract_no}）",
        f"總價：{_money(e.total_old)} → {_money(e.total_new)} 元（{sign}{_money(abs(diff))}），這是匯入 PCCES 後、重新總計之前的總價",
        "",
        f"改動（{len(e.edited)} 項）：",
        *_change_lines(r),
        "跟著重算的上層：",
        *(f"・{p.path} {p.name}：{_money(p.old)} → {_money(p.new)}" for p in e.parents),
        *(f"・{p.path or '頂層'} 底下的小計列「{p.name}」：{_money(p.old)} → {_money(p.new)}" for p in e.subtotals),
        f"・總計列與 TotalAmount、TotalAmountChinese：{_money(e.total_old)} → {_money(e.total_new)}",
        *_analysis_lines(r),
        "",
    ]
    if r.source_problems:
        out.append(f"底稿原本就有 {len(r.source_problems)} 處金額對不起來（不是這次改的）：")
        out.extend(f"　{p}" for p in r.source_problems)
    out.append("金額檢查（讀回寫出檔）：全部對得起來" if not r.output_problems
               else f"金額檢查（讀回寫出檔）：有 {len(r.output_problems)} 處對不起來")
    out.extend(f"　{p}" for p in r.output_problems)
    if e.not_updated:
        out += ["", "沒有跟著改的部分："]
        out.extend(f"・{n}" for n in e.not_updated)
    steps = [
        "匯入（專案建立‧轉入 → XML 電子檔轉入）時會先跳「此 XML 檔並非 PCCES 製作，匯入後計算結果可能不等於原總價金額」，"
        "再跳「本電子檔非 PCCES 產生，資料正確性請洽原投標廠商！」，都按確定，匯入照樣成功。"
        "專案目錄這一筆會是紅字、備註「非【PCCES】製作」；工程代碼重複時 PCCES 會自動加 -01 這類流水號。",
    ]
    if e.formula_items or e.quantity_changed or e.analyses:
        steps.append("匯入 PCCES 後要重新總計，公式項與資源統計才會更新，總價可能再變。")
    elif e.not_updated:
        steps.append("匯入 PCCES 後要重新總計，上面沒有跟著改的部分才會更新。")
    steps.append("要交出去之前在 PCCES 做自主檢查，再製作電子檔，由 PCCES 重新簽章。")
    out += ["", "匯入 PCCES："]
    out.extend(f"{i}. {s}" for i, s in enumerate(steps, 1))
    return "\n".join(out)


@mcp.tool()
def pcces_write_budget(
    source_path: str,
    edits: list[EditSpec],
    title_suffix: str | None = None,
) -> str:
    """以一份 PCCES 預算書（電子標單 XML）為底稿，改詳細表葉項的數量或單價、或單價分析組成列（工料）的數量或單價，重算分析單價、上層複價與總價後另存一份給 PCCES 匯入的 XML。

    原檔與 PCCES 資料庫都不動；輸出另存成新檔，寫在 source_path 同一個資料夾，檔名自動產生
    （<工程代碼>_edit_<日期>_<流水號>.xml）、不覆蓋任何既有檔，回傳完整路徑。
    source_path：PCCES 匯出的 .xml 絕對路徑（也可以是這支工具之前的輸出）。
    edits：要改的項目，每筆 {"item": 項次路徑, "quantity": 新數量, "price": 新單價, "component": 工料代碼（選填）}，
      quantity、price 至少給一個。任一筆不合規則就整批不寫，錯誤訊息會列出可用的項次或組成列。
      項次寫 pcces_read_budget（max_level=-1）顯示的項次：itemNo 已是完整項次（壹.一.1.1）就照寫，
      每層只寫一段（壹／一／2）就用「.」串成 壹.一.2；只能指到葉項，兩列撞成同一個項次會拒絕並列出候選。
      不帶 component：改詳細表葉項本身。一般項（general）、變動單價項（variablePrice）可改數量與單價；
        有單價分析的工項（analysis）只能改數量，單價要用 component 改它的組成。
        公式項（雜費、保險費、管理利潤、營業稅這類）不能改。數量小數位數不超過詳細表設定，單價最多 2 位小數。
      帶 component：改 item 那一項單價分析裡、工料代碼＝component 的那一列，quantity／price 是那一列的值
        （數量小數位數不超過單價分析表設定，單價最多 2 位小數）。數量只改這個分析的這一列；
        單價分兩種：一般工料（general）全案共用一個單價，所有分析裡同代碼的列與資源統計的單價一起改，回傳列出被連帶的分析；
        變動單價工料（variablePrice）只改這個分析。% 類（工具損耗這類）、巢狀分析列、鎖定單價的工料不能改；
        同一分析裡同代碼有兩列以上會拒絕並列候選。組成的工料代碼與每一列能不能改，先用 pcces_read_budget 帶 item 查；
        找不到代碼時錯誤訊息也會列出這個分析的全部組成。
        工具照 PCCES 規則重算組成複價、% 類、分析單價，再更新詳細表每一列用到這個分析的葉項；
        底稿的分析照規則重現不了就拒寫。
    title_suffix：選填，接在工程名稱後面，例如「（PCX改值）」，匯入 PCCES 後才分得出跟原案。
    複價照 PCCES 的規則算：單價先進位到詳細表的單價小數位數再乘數量；母項＝子項加總（不含小計列）；
    受影響的小計列跟著重算（有公式的照引用相加，沒有的＝同層前面非小計各列加總），回傳逐列列出；總價不含小計列。
    公式項、資源統計的數量與複價、人機料雜比例不重算，回傳會逐條列出；匯入 PCCES 後要重新總計才會更新，總價可能再變。
    """
    src = Path(source_path)
    if not src.is_absolute():
        raise ToolError(f"source_path 要給絕對路徑，收到的是：{source_path}")
    if not src.is_file():
        raise ToolError(f"找不到檔案：{source_path}。請確認使用者已從 PCCES 匯出 xml，並放在這個位置。")
    out = _out_dir(src)
    try:
        specs = [
            ItemEdit(
                path=e.item,
                quantity=None if e.quantity is None else to_decimal(e.quantity, f"{e.item} 的數量"),
                price=None if e.price is None else to_decimal(e.price, f"{e.item} 的單價"),
                component=e.component,
            )
            for e in edits
        ]
        r = write_edited(src, specs, out, title_suffix=title_suffix)
    except EditError as exc:
        raise ToolError(f"沒有寫出任何檔：{exc}") from exc
    except PermissionError as exc:
        # 底稿放在唯讀的共用資料夾時最常見；要使用者處理，不是參數錯
        raise ToolError(f"沒有寫出任何檔：{out} 不能寫入（{exc.strerror}）。請使用者把 XML 複製到可以寫入的資料夾（例如文件），再用新路徑叫一次。") from exc
    except (ValueError, ET.ParseError) as exc:
        raise ToolError(f"{source_path} 不能當底稿：{exc}") from exc
    return _render_write(r)


# ---------- 使用回報（只寫本機檔，使用者自己檢查後用 LINE 傳給開發者） ----------


@mcp.tool(
    annotations=ToolAnnotations(read_only_hint=False, destructive_hint=False, idempotent_hint=False, open_world_hint=False),
    structured_output=False,
)
def pcces_report_issue(
    summary: str,
    attempts: list[str],
    expected: str,
    actual: str,
    user_words: str = "",
) -> str:
    r"""把這個 session 用 PCCES 工具遇到的問題寫成一份使用回報（Markdown），存在使用者「文件」底下的 PCCES回報\，由使用者自己檢查刪改後用 LINE 傳給提供工具的同事；不上傳、不寄出。

    只在使用者同意寫回報之後才叫（工具一再回錯、同一步反覆失敗、使用者說結果不對時，照 pcces skill〈使用回報〉先問）。
    summary：問題摘要，一兩句：在做什麼、哪一步出了什麼問題。
    attempts：做了哪些嘗試，一項一筆、照先後順序：叫了哪支工具、參數重點、回了什麼錯或什麼結果。
    expected：期望的結果。actual：實際的結果。
    user_words：選填，使用者描述問題的原話。
    不要寫進任何欄位：單價、金額、總價、工程名稱，以及機關、地點這類認得出是哪個案子的資訊（預算書可能是客戶內部資訊）；
      要提就寫「某一項的單價」「這份預算書」。檔案路徑裡的使用者帳號名稱工具會自動換成 <user>。
    工具自動補時間、外掛版本、Windows 版本、這台有沒有裝 PCCES。檔名 <YYYYMMDD>_<流水號>.md，不覆蓋既有檔，回傳完整路徑
    與要轉告使用者的話。
    """
    r = Report(summary=summary, attempts=list(attempts or []), expected=expected, actual=actual, user_words=user_words or "")
    missing = r.missing()
    if missing:
        raise ToolError(f"沒有寫出回報：{'、'.join(missing)} 不能是空的。summary、attempts（至少一筆）、expected、actual 都要填，"
                        "user_words 可以省略；內容照使用者這次遇到的情況寫，不寫單價、金額、工程名稱。")
    try:
        path = write_report(r)
    except ReportError as exc:
        raise ToolError(f"沒有寫出回報：{exc}") from exc
    except OSError as exc:
        raise ToolError(f"沒有寫出回報：{path_hint()} 不能寫入（{exc.strerror or exc}）。請使用者確認「文件」資料夾可以寫入，再叫一次。") from exc
    return "\n".join([
        f"已存成 {path}",
        "請先打開看一下、刪掉不想給的內容，再用 LINE 把這個檔傳給提供這套工具的同事。",
        "",
        f"（給 Claude：把上面兩句轉告使用者。回報資料夾是 {path.parent}；先問他要不要幫他打開，要的話用 shell 跑 "
        f'explorer.exe "{path.parent}"（PowerShell 也可以 explorer.exe /select,"{path}" 直接選到這個檔；explorer 回退出碼 1 是正常的）。'
        "不要替他傳送，這套工具沒有自動回傳。）",
    ])


def main() -> None:
    mcp.run()


if __name__ == "__main__":
    main()
